  intro n, intro h,
  have h1 := Nat.mod_lt (n ^ 3 + 2 * n + 7) 41 h,
  rw [Nat.mod_eq_mod_of_lt h1],
  suffices h2 : (n ^ 3 + 2 * n + 7) % 41 ≠ 24,
