  suffices h3 : (n ^ 3 + 2 * n + 7) ≠ 24 + 41 * k,
    for some k : Nat, by contradiction, contradiction,
  by_cases h4 : n ^ 3 + 2 * n + 7 = 24 + 41 * k,
  { exact false.elim h3 h4 },
  { exact h2 h4 }
end",
  "report": "Established that for all natural numbers n less than 120, the expression (n^3 + 2n + 7) mod 41 is not equal to 24."
}

